def permutations(t):
    res, cur = [], []
    def explorer():
        if len(cur) == len(t):
            res.append(cur[:])
            return
        for x in t:
            if x not in cur:
                cur.append(x)
                explorer()
                cur.pop()
    explorer()
    return res

