def pieces(valeurs, montant):
    dp = [0] + [float("inf")] * montant
    for m in range(1, montant + 1):
        for v in valeurs:
            if v <= m:
                dp[m] = min(dp[m], dp[m - v] + 1)
    return dp[montant]
